-- Enable only the reviewed known Roost scope; no unresolved armour reward sets.
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS _roost_activation_guard;
CREATE TEMPORARY TABLE _roost_activation_guard(label VARCHAR(100)PRIMARY KEY,ok TINYINT NOT NULL,CHECK(ok=1))ENGINE=InnoDB;
INSERT INTO _roost_activation_guard VALUES('review',COALESCE(@roost_activation_reviewed,0)=1);
INSERT INTO _roost_activation_guard VALUES('tasks',(SELECT COUNT(*)FROM tasks WHERE id BETWEEN 3040501 AND 3040515)=15);
INSERT INTO _roost_activation_guard VALUES('activities',(SELECT COUNT(*)FROM task_activities WHERE taskid BETWEEN 3040501 AND 3040515)=54);
INSERT INTO _roost_activation_guard VALUES('criteria',(SELECT COUNT(*)FROM achievement_criteria WHERE (achievement_id=500050100 AND event_type=11 AND target_id IN(500050200,500050300,500050400,500050500))OR(achievement_id IN(500050200,500050300,500050400,500050500)AND event_type=4 AND target_id BETWEEN 3040501 AND 3040515))=19);
INSERT INTO _roost_activation_guard VALUES('sets',(SELECT COUNT(*)FROM reward_sets WHERE reward_set_id IN(3040506,3040507,3040508,3040509,3040512,3040513,3040514,3040515,3050503,3050504,3050505))=11);
INSERT INTO _roost_activation_guard VALUES('rewards',(SELECT COUNT(*)FROM rewards WHERE reward_id IN(305050310,305050320,305050410,305050411,305050420,305050421,305050510,305050511,305050520,305050521,304050602,304050603,304050604,304050605,304050606,304050701,304050702,304050801,304050802,304050901,304050902,304051201,304051202,304051301,304051302,304051402,304051502))=27);
START TRANSACTION;
UPDATE achievements SET enabled=1 WHERE id IN(500050100,500050200,500050300,500050400,500050500);
UPDATE achievement_criteria SET enabled=1 WHERE (achievement_id=500050100 AND event_type=11 AND target_id IN(500050200,500050300,500050400,500050500))OR(achievement_id IN(500050200,500050300,500050400,500050500)AND event_type=4 AND target_id BETWEEN 3040501 AND 3040515);
UPDATE tasks SET enabled=1 WHERE id BETWEEN 3040501 AND 3040515;
UPDATE tradeskill_recipe SET enabled=1 WHERE id IN(3042001,3042002);
UPDATE reward_sets SET enabled=1 WHERE reward_set_id IN(3040506,3040507,3040508,3040509,3040512,3040513,3040514,3040515,3050503,3050504,3050505);
UPDATE reward_sources SET enabled=1 WHERE reward_set_id IN(3040506,3040507,3040508,3040509,3040512,3040513,3040514,3040515,3050503,3050504,3050505);
UPDATE reward_options SET enabled=1 WHERE reward_set_id IN(3040506,3040507,3040508,3040509,3040512,3040513,3040514,3040515,3050503,3050504,3050505);
UPDATE rewards SET enabled=1 WHERE reward_id IN(305050310,305050320,305050410,305050411,305050420,305050421,305050510,305050511,305050520,305050521,304050602,304050603,304050604,304050605,304050606,304050701,304050702,304050801,304050802,304050901,304050902,304051201,304051202,304051301,304051302,304051402,304051502);
COMMIT;
